import { useState } from "react";

export default function App() {
  const [count, setCount] = useState<number>(0);

  const decrement = (): void => setCount((c) => c - 1);
  const increment = (): void => setCount((c) => c + 1);

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="bg-white rounded-xl shadow-md p-8 flex flex-col items-center gap-4">
        <h1 className="text-3xl font-semibold text-gray-800">Contador</h1>

        <div className="flex items-center gap-6">
          <button
            type="button"
            onClick={decrement}
            aria-label="Restar"
            className="w-12 h-12 rounded-full bg-red-500 text-white text-2xl font-bold hover:bg-red-600 active:scale-95 transition"
          >
            -
          </button>

          <span className="text-4xl font-bold text-gray-900 min-w-[3ch] text-center">
            {count}
          </span>

          <button
            type="button"
            onClick={increment}
            aria-label="Sumar"
            className="w-12 h-12 rounded-full bg-green-500 text-white text-2xl font-bold hover:bg-green-600 active:scale-95 transition"
          >
            +
          </button>
        </div>

        <p className="text-lg text-gray-700">El doble es {count * 2}</p>

        {count > 5 && (
          <p className="text-lg font-semibold text-blue-600">¡Más de 5!</p>
        )}
      </div>
    </div>
  );
}

