import { useState, type FormEvent } from "react";

export default function App() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [submittedEmail, setSubmittedEmail] = useState<string | null>(null);

  const isValid = email.includes("@") && password.length >= 8;

  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!isValid) return;
    setSubmittedEmail(email);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      {submittedEmail !== null ? (
        <p className="text-2xl font-semibold text-gray-800" role="status">
          Bienvenido, {submittedEmail}
        </p>
      ) : (
        <form
          onSubmit={handleSubmit}
          noValidate
          className="w-full max-w-sm bg-white rounded-xl shadow-md p-6 space-y-4"
        >
          <h1 className="text-xl font-bold text-gray-800">Iniciar sesión</h1>

          <div className="space-y-1">
            <label htmlFor="email" className="block text-sm font-medium text-gray-700">
              Email
            </label>
            <input
              id="email"
              name="email"
              type="email"
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full rounded-md border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div className="space-y-1">
            <label htmlFor="password" className="block text-sm font-medium text-gray-700">
              Contraseña
            </label>
            <input
              id="password"
              name="password"
              type="password"
              autoComplete="current-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full rounded-md border border-gray-300 px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <button
            type="submit"
            disabled={!isValid}
            className="w-full rounded-md bg-blue-600 px-4 py-2 font-medium text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-gray-400"
          >
            Entrar
          </button>
        </form>
      )}
    </div>
  );
}

