model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

page Shop "/" {
  state products: Product[] = [
    { id: "p1", name: "Remera", price: 15.5 },
    { id: "p2", name: "Pantalón", price: 32.99 },
    { id: "p3", name: "Zapatillas", price: 59.9 }
  ]
  state cart: CartItem[] = []
  computed total = cart.reduce((sum, c) => sum + c.price * c.qty, 0)

  fn add(p) {
    let existing = cart.find(c => c.id == p.id)
    if existing {
      cart = cart.map(c => c.id == p.id ? { ...c, qty: c.qty + 1 } : c)
    } else {
      cart = [...cart, { id: p.id, name: p.name, price: p.price, qty: 1 }]
    }
  }

  fn inc(id) {
    cart = cart.map(c => c.id == id ? { ...c, qty: c.qty + 1 } : c)
  }

  fn dec(id) {
    cart = cart
      .map(c => c.id == id ? { ...c, qty: c.qty - 1 } : c)
      .filter(c => c.qty > 0)
  }

  column gap=6 pad=6 {
    title "Tienda"
    card gap=3 pad=4 {
      title "Productos" small
      for p in products key p.id {
        row gap=3 align=center justify=between {
          text p.name bold
          text `$${p.price.toFixed(2)}` muted
          button "Agregar" primary -> add(p)
        }
      }
    }
    card gap=3 pad=4 {
      title "Carrito" small
      if cart.length == 0 {
        text "El carrito está vacío" muted
      } else {
        for c in cart key c.id {
          row gap=3 align=center justify=between {
            text c.name bold
            text `$${(c.price * c.qty).toFixed(2)}` muted
            row gap=2 align=center {
              button "-" small -> dec(c.id)
              text `${c.qty}`
              button "+" small -> inc(c.id)
            }
          }
        }
      }
      divider
      row justify=between {
        text "Total" bold
        text `$${total.toFixed(2)}` bold
      }
    }
  }
}

model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  id: ID
  name: String
  price: Number
  qty: Number
}

page Shop "/" {
  state products: Product[] = [
    { id: "p1", name: "Remera", price: 15.5 },
    { id: "p2", name: "Pantalón", price: 32.99 },
    { id: "p3", name: "Zapatillas", price: 59.9 }
  ]
  state cart: CartItem[] = []
  computed total = cart.reduce((s, x) => s + x.price * x.qty, 0)

  fn add(p) {
    let it = cart.find(x => x.id == p.id)
    if it {
      it.qty++
    } else {
      cart.push({ id: p.id, name: p.name, price: p.price, qty: 1 })
    }
  }

  fn inc(id) {
    let it = cart.find(x => x.id == id)
    if it {
      it.qty++
    }
  }

  fn dec(id) {
    let it = cart.find(x => x.id == id)
    if !it { return }
    if it.qty <= 1 {
      cart = cart.filter(x => x.id != id)
    } else {
      it.qty--
    }
  }

  column gap=6 pad=6 {
    title "Tienda"
    grid cols=1 md:cols=3 gap=4 {
      for p in products key p.id {
        card gap=2 pad=4 {
          text p.name bold
          text `$${p.price.toFixed(2)}` muted
          button "Agregar" primary -> add(p)
        }
      }
    }
    divider
    title "Carrito" small
    if cart.length == 0 {
      text "El carrito está vacío" muted
    } else {
      column gap=2 {
        for it in cart key it.id {
          row gap=3 align=center justify=between {
            text it.name
            row gap=2 align=center {
              button "-" small -> dec(it.id)
              text `${it.qty}` bold
              button "+" small -> inc(it.id)
            }
            text `$${(it.price * it.qty).toFixed(2)}`
          }
        }
      }
    }
    text `Total: $${total.toFixed(2)}` large bold
  }
}

