import { useState } from "react";

interface Product {
  id: number;
  name: string;
  price: number;
}

interface CartItem {
  product: Product;
  quantity: number;
}

const PRODUCTS: Product[] = [
  { id: 1, name: "Auriculares", price: 49.99 },
  { id: 2, name: "Teclado mecánico", price: 89.5 },
  { id: 3, name: "Mouse inalámbrico", price: 25.75 },
];

const formatPrice = (value: number): string => `$${value.toFixed(2)}`;

export default function App() {
  const [cart, setCart] = useState<CartItem[]>([]);

  const addToCart = (product: Product) => {
    setCart((prev) => {
      const existing = prev.find((item) => item.product.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.product.id === product.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...prev, { product, quantity: 1 }];
    });
  };

  const increment = (id: number) => {
    setCart((prev) =>
      prev.map((item) =>
        item.product.id === id ? { ...item, quantity: item.quantity + 1 } : item
      )
    );
  };

  const decrement = (id: number) => {
    setCart((prev) =>
      prev
        .map((item) =>
          item.product.id === id
            ? { ...item, quantity: item.quantity - 1 }
            : item
        )
        .filter((item) => item.quantity > 0)
    );
  };

  const total = cart.reduce(
    (sum, item) => sum + item.product.price * item.quantity,
    0
  );

  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="min-h-screen bg-gray-100 py-10 px-4">
      <div className="mx-auto max-w-4xl">
        <h1 className="mb-8 text-center text-3xl font-bold text-gray-800">
          Carrito de compras
        </h1>

        <div className="grid gap-6 md:grid-cols-2">
          <section className="rounded-xl bg-white p-6 shadow">
            <h2 className="mb-4 text-xl font-semibold text-gray-700">
              Productos
            </h2>
            <ul className="space-y-3">
              {PRODUCTS.map((product) => (
                <li
                  key={product.id}
                  className="flex items-center justify-between rounded-lg border border-gray-200 p-4"
                >
                  <div>
                    <p className="font-medium text-gray-800">{product.name}</p>
                    <p className="text-sm text-gray-500">
                      {formatPrice(product.price)}
                    </p>
                  </div>
                  <button
                    type="button"
                    onClick={() => addToCart(product)}
                    className="rounded-lg bg-blue-600 px-4 py-2 text-sm font-medium text-white transition hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-400"
                  >
                    Agregar
                  </button>
                </li>
              ))}
            </ul>
          </section>

          <section className="rounded-xl bg-white p-6 shadow">
            <h2 className="mb-4 text-xl font-semibold text-gray-700">
              Carrito{" "}
              <span className="text-sm font-normal text-gray-500">
                ({totalItems} {totalItems === 1 ? "ítem" : "ítems"})
              </span>
            </h2>

            {cart.length === 0 ? (
              <p className="py-8 text-center text-gray-400">
                El carrito está vacío.
              </p>
            ) : (
              <ul className="space-y-3">
                {cart.map((item) => (
                  <li
                    key={item.product.id}
                    className="flex items-center justify-between rounded-lg border border-gray-200 p-4"
                  >
                    <div>
                      <p className="font-medium text-gray-800">
                        {item.product.name}
                      </p>
                      <p className="text-sm text-gray-500">
                        {formatPrice(item.product.price)} ×{" "}
                        <span data-testid={`qty-${item.product.id}`}>
                          {item.quantity}
                        </span>{" "}
                        = {formatPrice(item.product.price * item.quantity)}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        onClick={() => decrement(item.product.id)}
                        aria-label={`Quitar una unidad de ${item.product.name}`}
                        className="h-8 w-8 rounded-full bg-gray-200 font-bold text-gray-700 transition hover:bg-gray-300"
                      >
                        -
                      </button>
                      <span className="w-6 text-center font-semibold">
                        {item.quantity}
                      </span>
                      <button
                        type="button"
                        onClick={() => increment(item.product.id)}
                        aria-label={`Agregar una unidad de ${item.product.name}`}
                        className="h-8 w-8 rounded-full bg-gray-200 font-bold text-gray-700 transition hover:bg-gray-300"
                      >
                        +
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            )}

            <div className="mt-6 flex items-center justify-between border-t border-gray-200 pt-4">
              <span className="text-lg font-semibold text-gray-700">
                Total
              </span>
              <span className="text-2xl font-bold text-gray-900">
                {formatPrice(total)}
              </span>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";

type Product = {
  id: number;
  nombre: string;
  precio: number;
};

type CartItem = {
  product: Product;
  cantidad: number;
};

const PRODUCTS: Product[] = [
  { id: 1, nombre: "Auriculares", precio: 49.99 },
  { id: 2, nombre: "Teclado mecánico", precio: 89.5 },
  { id: 3, nombre: "Mouse inalámbrico", precio: 25.75 },
];

const formatPrice = (value: number): string => `$${value.toFixed(2)}`;

export default function App() {
  const [cart, setCart] = useState<CartItem[]>([]);

  const addToCart = (product: Product) => {
    setCart((prev) => {
      const exists = prev.some((item) => item.product.id === product.id);
      if (exists) {
        return prev.map((item) =>
          item.product.id === product.id
            ? { ...item, cantidad: item.cantidad + 1 }
            : item
        );
      }
      return [...prev, { product, cantidad: 1 }];
    });
  };

  const increment = (id: number) => {
    setCart((prev) =>
      prev.map((item) =>
        item.product.id === id ? { ...item, cantidad: item.cantidad + 1 } : item
      )
    );
  };

  const decrement = (id: number) => {
    setCart((prev) =>
      prev
        .map((item) =>
          item.product.id === id
            ? { ...item, cantidad: item.cantidad - 1 }
            : item
        )
        .filter((item) => item.cantidad > 0)
    );
  };

  const totalCents = cart.reduce(
    (sum, item) => sum + Math.round(item.product.precio * 100) * item.cantidad,
    0
  );
  const total = totalCents / 100;

  return (
    <div className="min-h-screen bg-gray-100 p-6">
      <div className="mx-auto max-w-4xl">
        <h1 className="mb-6 text-3xl font-bold text-gray-800">
          Carrito de compras
        </h1>

        <div className="grid gap-6 md:grid-cols-2">
          <section className="rounded-lg bg-white p-5 shadow">
            <h2 className="mb-4 text-xl font-semibold text-gray-700">
              Productos
            </h2>
            <ul className="space-y-3">
              {PRODUCTS.map((product) => (
                <li
                  key={product.id}
                  className="flex items-center justify-between rounded border border-gray-200 p-3"
                >
                  <div>
                    <p className="font-medium text-gray-800">
                      {product.nombre}
                    </p>
                    <p className="text-sm text-gray-500">
                      {formatPrice(product.precio)}
                    </p>
                  </div>
                  <button
                    type="button"
                    onClick={() => addToCart(product)}
                    className="rounded bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
                  >
                    Agregar
                  </button>
                </li>
              ))}
            </ul>
          </section>

          <section className="rounded-lg bg-white p-5 shadow">
            <h2 className="mb-4 text-xl font-semibold text-gray-700">
              Tu carrito
            </h2>

            {cart.length === 0 ? (
              <p className="text-gray-500">El carrito está vacío.</p>
            ) : (
              <ul className="space-y-3">
                {cart.map((item) => (
                  <li
                    key={item.product.id}
                    className="flex items-center justify-between rounded border border-gray-200 p-3"
                  >
                    <div>
                      <p className="font-medium text-gray-800">
                        {item.product.nombre}
                      </p>
                      <p className="text-sm text-gray-500">
                        {formatPrice(item.product.precio)} × {item.cantidad} ={" "}
                        {formatPrice(
                          (Math.round(item.product.precio * 100) *
                            item.cantidad) /
                            100
                        )}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      <button
                        type="button"
                        onClick={() => decrement(item.product.id)}
                        aria-label={`Quitar una unidad de ${item.product.nombre}`}
                        className="h-8 w-8 rounded bg-gray-200 font-bold text-gray-700 hover:bg-gray-300"
                      >
                        -
                      </button>
                      <span className="w-6 text-center font-medium">
                        {item.cantidad}
                      </span>
                      <button
                        type="button"
                        onClick={() => increment(item.product.id)}
                        aria-label={`Agregar una unidad de ${item.product.nombre}`}
                        className="h-8 w-8 rounded bg-gray-200 font-bold text-gray-700 hover:bg-gray-300"
                      >
                        +
                      </button>
                    </div>
                  </li>
                ))}
              </ul>
            )}

            <div className="mt-6 flex items-center justify-between border-t border-gray-200 pt-4">
              <span className="text-lg font-semibold text-gray-700">
                Total:
              </span>
              <span className="text-lg font-bold text-gray-900">
                {formatPrice(total)}
              </span>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}

