import { useState } from "react";

type TabId = "perfil" | "ajustes" | "ayuda";

interface Tab {
  id: TabId;
  label: string;
  title: string;
  content: string;
}

const TABS: Tab[] = [
  {
    id: "perfil",
    label: "Perfil",
    title: "Tu perfil",
    content:
      "Acá podés ver y editar tu información personal: nombre, foto, correo electrónico y una breve descripción sobre vos.",
  },
  {
    id: "ajustes",
    label: "Ajustes",
    title: "Ajustes de la cuenta",
    content:
      "Configurá tus preferencias: idioma, notificaciones, privacidad y tema de la aplicación. Los cambios se guardan automáticamente.",
  },
  {
    id: "ayuda",
    label: "Ayuda",
    title: "Centro de ayuda",
    content:
      "¿Tenés dudas? Consultá las preguntas frecuentes o escribinos a soporte@ejemplo.com y te responderemos a la brevedad.",
  },
];

export default function App() {
  const [activeTab, setActiveTab] = useState<TabId>("perfil");

  const current = TABS.find((tab) => tab.id === activeTab) ?? TABS[0];

  const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const index = TABS.findIndex((tab) => tab.id === activeTab);
    let nextIndex = index;
    if (e.key === "ArrowRight") nextIndex = (index + 1) % TABS.length;
    else if (e.key === "ArrowLeft") nextIndex = (index - 1 + TABS.length) % TABS.length;
    else if (e.key === "Home") nextIndex = 0;
    else if (e.key === "End") nextIndex = TABS.length - 1;
    else return;

    e.preventDefault();
    const nextId = TABS[nextIndex].id;
    setActiveTab(nextId);
    document.getElementById(`tab-${nextId}`)?.focus();
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-start justify-center p-6 sm:p-12">
      <div className="w-full max-w-2xl bg-white rounded-2xl shadow-lg overflow-hidden">
        <header className="px-6 pt-6">
          <h1 className="text-2xl font-bold text-slate-800">Mi cuenta</h1>
          <p className="text-sm text-slate-500 mt-1">
            Elegí una pestaña para ver su contenido.
          </p>
        </header>

        <div
          role="tablist"
          aria-label="Secciones de la cuenta"
          onKeyDown={handleKeyDown}
          className="flex gap-2 px-6 mt-6 border-b border-slate-200"
        >
          {TABS.map((tab) => {
            const isActive = tab.id === activeTab;
            return (
              <button
                key={tab.id}
                id={`tab-${tab.id}`}
                type="button"
                role="tab"
                aria-selected={isActive}
                aria-controls={`panel-${tab.id}`}
                tabIndex={isActive ? 0 : -1}
                onClick={() => setActiveTab(tab.id)}
                className={`-mb-px px-4 py-2 text-sm font-medium rounded-t-lg border-b-2 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 ${
                  isActive
                    ? "border-indigo-600 text-indigo-600 bg-indigo-50"
                    : "border-transparent text-slate-500 hover:text-slate-700 hover:bg-slate-50"
                }`}
              >
                {tab.label}
              </button>
            );
          })}
        </div>

        <section
          id={`panel-${current.id}`}
          role="tabpanel"
          aria-labelledby={`tab-${current.id}`}
          tabIndex={0}
          className="p-6 focus:outline-none"
        >
          <h2 className="text-lg font-semibold text-slate-800">{current.title}</h2>
          <p className="mt-2 text-slate-600 leading-relaxed">{current.content}</p>
        </section>
      </div>
    </div>
  );
