import { useState } from "react";

type TabId = "perfil" | "ajustes" | "ayuda";

interface Tab {
  id: TabId;
  label: string;
  content: string;
}

const TABS: Tab[] = [
  {
    id: "perfil",
    label: "Perfil",
    content:
      "Acá podés ver y editar la información de tu perfil: nombre, foto, biografía y datos de contacto.",
  },
  {
    id: "ajustes",
    label: "Ajustes",
    content:
      "Configurá tus preferencias: idioma, notificaciones, privacidad y apariencia de la aplicación.",
  },
  {
    id: "ayuda",
    label: "Ayuda",
    content:
      "¿Tenés dudas? Consultá las preguntas frecuentes o contactá a nuestro equipo de soporte.",
  },
];

export default function App() {
  const [activeTab, setActiveTab] = useState<TabId>("perfil");

  const current = TABS.find((t) => t.id === activeTab) ?? TABS[0];

  const handleKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>, index: number) => {
    let nextIndex: number | null = null;
    if (e.key === "ArrowRight") nextIndex = (index + 1) % TABS.length;
    if (e.key === "ArrowLeft") nextIndex = (index - 1 + TABS.length) % TABS.length;
    if (e.key === "Home") nextIndex = 0;
    if (e.key === "End") nextIndex = TABS.length - 1;
    if (nextIndex !== null) {
      e.preventDefault();
      const next = TABS[nextIndex];
      setActiveTab(next.id);
      document.getElementById(`tab-${next.id}`)?.focus();
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 flex items-start justify-center p-6">
      <div className="w-full max-w-xl mt-12 bg-white rounded-xl shadow-md overflow-hidden">
        <div
          role="tablist"
          aria-label="Secciones"
          className="flex border-b border-gray-200"
        >
          {TABS.map((tab, index) => {
            const isActive = tab.id === activeTab;
            return (
              <button
                key={tab.id}
                id={`tab-${tab.id}`}
                type="button"
                role="tab"
                aria-selected={isActive}
                aria-controls={`panel-${tab.id}`}
                tabIndex={isActive ? 0 : -1}
                onClick={() => setActiveTab(tab.id)}
                onKeyDown={(e) => handleKeyDown(e, index)}
                className={`flex-1 px-4 py-3 text-sm font-medium transition-colors border-b-2 -mb-px focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-400 ${
                  isActive
                    ? "border-blue-600 text-blue-600 bg-blue-50"
                    : "border-transparent text-gray-600 hover:text-gray-900 hover:bg-gray-50"
                }`}
              >
                {tab.label}
              </button>
            );
          })}
        </div>

        <div
          id={`panel-${current.id}`}
          role="tabpanel"
          aria-labelledby={`tab-${current.id}`}
          className="p-6"
        >
          <h2 className="text-lg font-semibold text-gray-800 mb-2">{current.label}</h2>
          <p className="text-gray-600 leading-relaxed">{current.content}</p>
        </div>
      </div>
    </div>
  );
}

