import { useEffect, useState } from "react";

type User = { id: number; name: string; email: string };

export default function App() {
  const [users, setUsers] = useState<User[]>([]);
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");

  const load = async () => {
    try {
      const res = await fetch("/api/users");
      if (res.ok) setUsers(await res.json());
    } catch {
      // ignore
    }
  };

  useEffect(() => {
    load();
  }, []);

  const add = async () => {
    if (!email.includes("@")) {
      setError("Email inválido");
      return;
    }
    setError("");
    try {
      const res = await fetch("/api/users", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name, email }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        setError(data.error || "Error al agregar");
        return;
      }
      setName("");
      setEmail("");
      await load();
    } catch {
      setError("Error de conexión");
    }
  };

  const remove = async (id: number) => {
    try {
      await fetch(`/api/users/${id}`, { method: "DELETE" });
      await load();
    } catch {
      // ignore
    }
  };

  return (
    <div className="max-w-xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-4">Usuarios</h1>
      <div className="flex gap-2 mb-2">
        <input
          className="border rounded px-2 py-1 flex-1"
          placeholder="Nombre"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <input
          className="border rounded px-2 py-1 flex-1"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <button className="bg-blue-600 text-white rounded px-3 py-1" onClick={add}>
          Agregar
        </button>
      </div>
      {error && <p className="text-red-600 mb-2">{error}</p>}
      <ul className="space-y-2">
        {users.map((u) => (
          <li key={u.id} className="flex items-center justify-between border rounded p-2">
            <div>
              <span className="font-medium">{u.name}</span>{" "}
              <span className="text-gray-600">{u.email}</span>
            </div>
            <button className="bg-red-600 text-white rounded px-2 py-1" onClick={() => remove(u.id)}>
              Borrar
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}

