import { useEffect, useState } from "react";

type Item = {
  id: number;
  name: string;
  bought: boolean;
};

export default function App() {
  const [items, setItems] = useState<Item[]>([]);
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = async () => {
    try {
      const res = await fetch("/api/items");
      if (!res.ok) throw new Error("Error al cargar");
      const data: Item[] = await res.json();
      setItems(data);
      setError(null);
    } catch {
      setError("No se pudo cargar la lista");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const addItem = async () => {
    const trimmed = name.trim();
    if (!trimmed) return;
    try {
      const res = await fetch("/api/items", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: trimmed }),
      });
      if (!res.ok) throw new Error();
      const item: Item = await res.json();
      setItems((prev) => [...prev, item]);
      setName("");
      setError(null);
    } catch {
      setError("No se pudo agregar el producto");
    }
  };

  const markBought = async (id: number) => {
    try {
      const res = await fetch(`/api/items/${id}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ bought: true }),
      });
      if (!res.ok) throw new Error();
      const updated: Item = await res.json();
      setItems((prev) => prev.map((it) => (it.id === id ? updated : it)));
      setError(null);
    } catch {
      setError("No se pudo actualizar el producto");
    }
  };

  const deleteItem = async (id: number) => {
    try {
      const res = await fetch(`/api/items/${id}`, { method: "DELETE" });
      if (!res.ok) throw new Error();
      setItems((prev) => prev.filter((it) => it.id !== id));
      setError(null);
    } catch {
      setError("No se pudo borrar el producto");
    }
  };

  const pending = items.filter((it) => !it.bought).length;

  return (
    <div className="min-h-screen bg-gray-100 flex justify-center p-6">
      <div className="w-full max-w-md bg-white rounded-xl shadow p-6">
        <h1 className="text-2xl font-bold mb-2">Lista de compras</h1>
        <p className="text-gray-600 mb-4">{`${pending} por comprar`}</p>

        <form
          className="flex gap-2 mb-4"
          onSubmit={(e) => {
            e.preventDefault();
            addItem();
          }}
        >
          <input
            className="flex-1 border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-400"
            placeholder="Producto"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <button
            type="submit"
            className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
          >
            Agregar
          </button>
        </form>

        {error && <p className="text-red-600 mb-3">{error}</p>}
        {loading && <p className="text-gray-500">Cargando...</p>}

        <ul className="space-y-2">
          {items.map((item) => (
            <li
              key={item.id}
              className="flex items-center justify-between border border-gray-200 rounded px-3 py-2"
            >
              <span className={item.bought ? "line-through text-gray-500" : ""}>
                {item.name}
                {item.bought && <span className="ml-2 text-green-600">✓</span>}
              </span>
              <div className="flex gap-2">
                <button
                  className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700 disabled:opacity-50"
                  onClick={() => markBought(item.id)}
                  disabled={item.bought}
                >
                  Comprado
                </button>
                <button
                  className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700"
                  onClick={() => deleteItem(item.id)}
                >
                  Borrar
                </button>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

