import http from "node:http";

type Item = {
  id: number;
  name: string;
  bought: boolean;
};

const items: Item[] = [];
let nextId = 1;

function sendJson(res: http.ServerResponse, status: number, data: unknown) {
  const body = JSON.stringify(data);
  res.writeHead(status, {
    "Content-Type": "application/json; charset=utf-8",
    "Content-Length": Buffer.byteLength(body),
  });
  res.end(body);
}

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (chunk) => {
      data += chunk;
      if (data.length > 1e6) {
        reject(new Error("Body too large"));
        req.destroy();
      }
    });
    req.on("end", () => {
      if (!data) return resolve({});
      try {
        resolve(JSON.parse(data));
      } catch {
        reject(new Error("Invalid JSON"));
      }
    });
    req.on("error", reject);
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url || "/", "http://localhost");
  const path = url.pathname.replace(/\/+$/, "");
  const method = req.method || "GET";

  try {
    if (path === "/api/items") {
      if (method === "GET") {
        return sendJson(res, 200, items);
      }
      if (method === "POST") {
        const body = await readBody(req);
        const name = typeof body.name === "string" ? body.name.trim() : "";
        if (!name) return sendJson(res, 400, { error: "Nombre requerido" });
        const item: Item = { id: nextId++, name, bought: false };
        items.push(item);
        return sendJson(res, 201, item);
      }
      return sendJson(res, 405, { error: "Método no permitido" });
    }

    const match = path.match(/^\/api\/items\/(\d+)$/);
    if (match) {
      const id = Number(match[1]);
      const index = items.findIndex((it) => it.id === id);
      if (index === -1) return sendJson(res, 404, { error: "No encontrado" });

      if (method === "GET") {
        return sendJson(res, 200, items[index]);
      }
      if (method === "PATCH" || method === "PUT") {
        const body = await readBody(req);
        if (typeof body.bought === "boolean") items[index].bought = body.bought;
        if (typeof body.name === "string" && body.name.trim()) {
          items[index].name = body.name.trim();
        }
        return sendJson(res, 200, items[index]);
      }
      if (method === "DELETE") {
        const [removed] = items.splice(index, 1);
        return sendJson(res, 200, removed);
      }
      return sendJson(res, 405, { error: "Método no permitido" });
    }

    return sendJson(res, 404, { error: "No encontrado" });
  } catch (err) {
    return sendJson(res, 400, { error: (err as Error).message || "Error" });
  }
});

const PORT = Number(process.env.PORT) || 3000;
server.listen(PORT, () => {
  console.log(`Servidor escuchando en el puerto ${PORT}`);
});

