        {item.name}
        {!item.active && <span className="ml-1 text-gray-500 font-normal">(inactivo)</span>}
      </span>
      <span>Sueldo: {item.amount}</span>
      <button onClick={() => onToggle(item.id)}>Alternar</button>
    </div>
  );
}

