files.EmployeesPage.tsx:
import { useState } from "react";
import { SEED, type Item } from "./data";
import EmployeesForm from "./EmployeesForm";
import EmployeesList from "./EmployeesList";

export default function EmployeesPage() {
  const [items, setItems] = useState<Item[]>(SEED.map((i) => ({ ...i })));

  function add(name: string, amount: number) {
    setItems((prev) => [...prev, { id: Date.now(), name, amount, active: true }]);
  }

  function toggle(id: number) {
    setItems((prev) => prev.map((i) => (i.id === id ? { ...i, active: !i.active } : i)));
  }

  return (
    <div className="flex flex-col gap-2">
      <h2 className="text-xl font-bold">Empleados</h2>
      <EmployeesForm onAdd={add} />
      <EmployeesList items={items} onToggle={toggle} />
    </div>
  );
}

files.EmployeesRow.tsx:
import type { Item } from "./data";

export default function EmployeesRow({ item, onToggle }: { item: Item; onToggle: (id: number) => void }) {
  return (
    <div className="flex gap-2 items-center">
      <span className="font-semibold">
        {item.name}
        {!item.active && <span className="ml-1 font-normal text-gray-500">(inactivo)</span>}
      </span>
      <span>Sueldo: {item.amount}</span>
      <button
        type="button"
        className="px-2 py-0.5 border rounded text-sm hover:bg-gray-100"
        onClick={() => onToggle(item.id)}
      >
        Alternar
      </button>
    </div>
  );
}

